body {
    background-color: #050505;
    color: #e5e2e1;
    overflow-x: hidden;
    cursor: none; /* Hide default cursor for custom glow */
}

/* Custom Cursor Glow */
#cursor-glow {
    position: fixed;
    top: 0;
    left: 0;
    width: 400px;
    height: 400px;
    background: radial-gradient(circle, rgba(0, 122, 255, 0.15) 0%, rgba(0, 0, 0, 0) 70%);
    border-radius: 50%;
    pointer-events: none;
    transform: translate(-50%, -50%);
    z-index: 9999;
    transition: width 0.3s ease, height 0.3s ease, background 0.3s ease;
    mix-blend-mode: screen;
}

#cursor-dot {
    position: fixed;
    top: 0;
    left: 0;
    width: 8px;
    height: 8px;
    background-color: #adc6ff;
    border-radius: 50%;
    pointer-events: none;
    transform: translate(-50%, -50%);
    z-index: 10000;
    box-shadow: 0 0 10px rgba(173, 198, 255, 0.8);
}

/* Glassmorphism utilities */
.glass-card {
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(255, 255, 255, 0.1);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    position: relative;
    overflow: hidden;
}

.glass-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 1px;
    background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.1), transparent);
}

.bento-glow-hover {
    position: relative;
}

.bento-glow-hover::after {
    content: '';
    position: absolute;
    inset: 0;
    background: radial-gradient(600px circle at var(--mouse-x) var(--mouse-y), rgba(173, 198, 255, 0.06), transparent 40%);
    opacity: 0;
    transition: opacity 0.5s;
    pointer-events: none;
    z-index: -1;
}

.bento-glow-hover:hover::after {
    opacity: 1;
}

/* Magnetic Text Animation */
.magnetic-text-container {
    perspective: 1000px;
}

.magnetic-text {
    display: inline-block;
    transition: transform 0.1s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    transform-style: preserve-3d;
}

/* Horizontal Scroll Hide Scrollbar */
.hide-scrollbar::-webkit-scrollbar {
    display: none;
}
.hide-scrollbar {
    -ms-overflow-style: none;
    scrollbar-width: none;
}

index.scripts:
// Custom Cursor Logic
const cursorGlow = document.getElementById('cursor-glow');
const cursorDot = document.getElementById('cursor-dot');
let mouseX = window.innerWidth / 2;
let mouseY = window.innerHeight / 2;

document.addEventListener('mousemove', (e) => {
    mouseX = e.clientX;
    mouseY = e.clientY;

    // Move dot instantly
    cursorDot.style.left = `${mouseX}px`;
    cursorDot.style.top = `${mouseY}px`;

    // Move glow with slight delay/smoothness (handled by CSS transition initially, but requestAnimationFrame is smoother)
    cursorGlow.style.left = `${mouseX}px`;
    cursorGlow.style.top = `${mouseY}px`;
});

// Hover effect for interactive elements
const interactives = document.querySelectorAll('a, button, .cursor-pointer');
interactives.forEach(el => {
    el.addEventListener('mouseenter', () => {
        cursorGlow.style.width = '100px';
        cursorGlow.style.height = '100px';
        cursorGlow.style.background = 'radial-gradient(circle, rgba(173, 198, 255, 0.4) 0%, rgba(0, 0, 0, 0) 70%)';
        cursorDot.style.transform = 'translate(-50%, -50%) scale(1.5)';
    });
    el.addEventListener('mouseleave', () => {
        cursorGlow.style.width = '400px';
        cursorGlow.style.height = '400px';
        cursorGlow.style.background = 'radial-gradient(circle, rgba(0, 122, 255, 0.15) 0%, rgba(0, 0, 0, 0) 70%)';
        cursorDot.style.transform = 'translate(-50%, -50%) scale(1)';
    });
});

// Bento Card Glow Effect (mouse tracking relative to card)
document.getElementById('bento-container').addEventListener('mousemove', e => {
    for(const card of document.querySelectorAll('.bento-glow-hover')) {
        const rect = card.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;

        card.style.setProperty('--mouse-x', `${x}px`);
        card.style.setProperty('--mouse-y', `${y}px`);
    }
});

// Magnetic Text Effect for Hero Title
const title = document.getElementById('hero-title');
title.addEventListener('mousemove', (e) => {
    const rect = title.getBoundingClientRect();
    const x = e.clientX - rect.left - rect.width / 2;
    const y = e.clientY - rect.top - rect.height / 2;

    // Calculate rotation based on mouse position relative to center
    const xRotation = -y / 10;
    const yRotation = x / 10;

    title.style.transform = `rotateX(${xRotation}deg) rotateY(${yRotation}deg) translateZ(20px)`;
});

title.addEventListener('mouseleave', () => {
    title.style.transform = 'rotateX(0) rotateY(0) translateZ(0)';
});

// Horizontal Scroll Dragging Logic
const slider = document.getElementById('horizontal-scroll');
let isDown = false;
let startX;
let scrollLeft;

slider.addEventListener('mousedown', (e) => {
    isDown = true;
    startX = e.pageX - slider.offsetLeft;
    scrollLeft = slider.scrollLeft;
});
slider.addEventListener('mouseleave', () => {
    isDown = false;
});
slider.addEventListener('mouseup', () => {
    isDown = false;
});
slider.addEventListener('mousemove', (e) => {
    if (!isDown) return;
    e.preventDefault();
    const x = e.pageX - slider.offsetLeft;
    const walk = (x - startX) * 2; // Scroll-fast
    slider.scrollLeft = scrollLeft - walk;
});

