// Custom Cursor Logic
const cursorTrail = document.getElementById('cursor-trail');
const cursorDot = document.getElementById('cursor-dot');
let mouseX = window.innerWidth / 2;
let mouseY = window.innerHeight / 2;
let trailX = window.innerWidth / 2;
let trailY = window.innerHeight / 2;

document.addEventListener('mousemove', (e) => {
    mouseX = e.clientX;
    mouseY = e.clientY;

    // Move dot instantly
    cursorDot.style.left = `${mouseX}px`;
    cursorDot.style.top = `${mouseY}px`;
});

// Smooth trailing cursor loop
function animateCursor() {
    // Lerp
    trailX += (mouseX - trailX) * 0.15;
    trailY += (mouseY - trailY) * 0.15;

    cursorTrail.style.left = `${trailX}px`;
    cursorTrail.style.top = `${trailY}px`;

    requestAnimationFrame(animateCursor);
}
animateCursor();

// Particle Ripple Effect on Click
document.addEventListener('click', (e) => {
    createParticles(e.clientX, e.clientY);
});

function createParticles(x, y) {
    for (let i = 0; i < 8; i++) {
        const particle = document.createElement('div');
        particle.className = 'particle';
        document.body.appendChild(particle);

        const size = Math.random() * 6 + 2;
        particle.style.width = `${size}px`;
        particle.style.height = `${size}px`;
        particle.style.background = '#007AFF';
        particle.style.left = `${x}px`;
        particle.style.top = `${y}px`;

        const angle = Math.random() * Math.PI * 2;
        const distance = Math.random() * 50 + 20;
        const tx = Math.cos(angle) * distance;
        const ty = Math.sin(angle) * distance;

        particle.animate([
            { transform: 'translate(0, 0) scale(1)', opacity: 1 },
            { transform: `translate(${tx}px, ${ty}px) scale(0)`, opacity: 0 }
        ], {
            duration: 600 + Math.random() * 400,
            easing: 'cubic-bezier(0, .9, .57, 1)'
        }).onfinish = () => particle.remove();
    }
}

// Magnetic Button Effect
const magneticBtns = document.querySelectorAll('.magnetic-btn');
magneticBtns.forEach(btn => {
    btn.addEventListener('mousemove', (e) => {
        const rect = btn.getBoundingClientRect();
        const h = rect.width / 2;
        const w = rect.height / 2;
        const x = e.clientX - rect.left - h;
        const y = e.clientY - rect.top - w;

        btn.style.transform = `translate(${x * 0.3}px, ${y * 0.3}px)`;
        btn.style.transition = 'transform 0.1s ease-out';
    });

    btn.addEventListener('mouseleave', () => {
        btn.style.transform = 'translate(0px, 0px)';
        btn.style.transition = 'transform 0.5s ease-out';
    });
});

// Interactive hover states for cursor
const interactives = document.querySelectorAll('a, button, .cursor-pointer');
interactives.forEach(el => {
    el.addEventListener('mouseenter', () => {
        cursorTrail.style.width = '60px';
        cursorTrail.style.height = '60px';
        cursorTrail.style.borderColor = 'rgba(173, 198, 255, 0.8)';
    });
    el.addEventListener('mouseleave', () => {
        cursorTrail.style.width = '40px';
        cursorTrail.style.height = '40px';
        cursorTrail.style.borderColor = 'rgba(0, 122, 255, 0.8)';
    });
});

// Bento Card Glow Effect
document.getElementById('bento-container').addEventListener('mousemove', e => {
    for(const card of document.querySelectorAll('.bento-glow-hover')) {
        const rect = card.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;

        card.style.setProperty('--mouse-x', `${x}px`);
        card.style.setProperty('--mouse-y', `${y}px`);
    }
});

// Intersection Observer for Fade-in-up animations
const observerOptions = {
    root: null,
    rootMargin: '0px',
    threshold: 0.1
};

const observer = new IntersectionObserver((entries, observer) => {
    entries.forEach(entry => {
        if (entry.isIntersecting) {
            // Add delay based on inline classes if present
            let delay = 0;
            if(entry.target.classList.contains('delay-100')) delay = 100;
            if(entry.target.classList.contains('delay-200')) delay = 200;
            if(entry.target.classList.contains('delay-300')) delay = 300;
            if(entry.target.classList.contains('delay-400')) delay = 400;
            if(entry.target.classList.contains('delay-500')) delay = 500;

            setTimeout(() => {
                entry.target.classList.add('visible');
            }, delay);
            observer.unobserve(entry.target);
        }
    });
}, observerOptions);

document.querySelectorAll('.fade-in-up').forEach(el => {
    observer.observe(el);
});

// Horizontal Scroll Dragging Logic
const slider = document.getElementById('horizontal-scroll');
let isDown = false;
let startX;
let scrollLeft;

slider.addEventListener('mousedown', (e) => {
    isDown = true;
    startX = e.pageX - slider.offsetLeft;
    scrollLeft = slider.scrollLeft;
});
slider.addEventListener('mouseleave', () => {
    isDown = false;
});
slider.addEventListener('mouseup', () => {
    isDown = false;
});
slider.addEventListener('mousemove', (e) => {
    if (!isDown) return;
    e.preventDefault();
    const x = e.pageX - slider.offsetLeft;
    const walk = (x - startX) * 2;
    slider.scrollLeft = scrollLeft - walk;
});

// Three.js Background Animation (Spline replacement)
const initThreeJS = () => {
    const canvas = document.getElementById('hero-canvas');
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);

    const renderer = new THREE.WebGLRenderer({ canvas: canvas, alpha: true, antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(window.devicePixelRatio);

    // Create a complex wireframe mesh
    const geometry = new THREE.IcosahedronGeometry(2, 2);
    const material = new THREE.MeshBasicMaterial({ 
        color: 0x007AFF, 
        wireframe: true,
        transparent: true,
        opacity: 0.15
    });
    const mesh = new THREE.Mesh(geometry, material);
    scene.add(mesh);

    // Add particles
    const particlesGeometry = new THREE.BufferGeometry();
    const particlesCount = 200;
    const posArray = new Float32Array(particlesCount * 3);
    for(let i = 0; i < particlesCount * 3; i++) {
        posArray[i] = (Math.random() - 0.5) * 15;
    }
    particlesGeometry.setAttribute('position', new THREE.BufferAttribute(posArray, 3));
    const particlesMaterial = new THREE.PointsMaterial({
        size: 0.02,
        color: 0xadc6ff,
        transparent: true,
        opacity: 0.5
    });
    const particlesMesh = new THREE.Points(particlesGeometry, particlesMaterial);
    scene.add(particlesMesh);

    camera.position.z = 5;

    // Animation Loop
    let mouseTargetX = 0;
    let mouseTargetY = 0;

    document.addEventListener('mousemove', (event) => {
        mouseTargetX = (event.clientX / window.innerWidth) * 2 - 1;
        mouseTargetY = -(event.clientY / window.innerHeight) * 2 + 1;
    });

    const animate = () => {
        requestAnimationFrame(animate);

        // Slow rotation
        mesh.rotation.x += 0.001;
        mesh.rotation.y += 0.002;

        particlesMesh.rotation.y -= 0.0005;

        // Mouse interaction parallax
        mesh.position.x += (mouseTargetX * 0.5 - mesh.position.x) * 0.05;
        mesh.position.y += (mouseTargetY * 0.5 - mesh.position.y) * 0.05;

        particlesMesh.position.x += (mouseTargetX * 0.2 - particlesMesh.position.x) * 0.05;
        particlesMesh.position.y += (mouseTargetY * 0.2 - particlesMesh.position.y) * 0.05;

        renderer.render(scene, camera);
    };

    animate();

    // Handle Resize
    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });
};

// Initialize ThreeJS after a slight delay to ensure DOM is ready
setTimeout(initThreeJS, 100);

